// Raw skills are bind-mounted as subdirectories (e.g. skills-raw/analyze-data/SKILL.md).
// The Claude Code CLI expects flat .md files in ~/.claude/skills/ (e.g. skills/analyze-data.md).
// We read from RAW and sync flat files into SKILLS_DIR so the CLI can discover them.
const RAW_SKILLS_DIR = join(homedir(), ".claude", "skills-raw");
const SKILLS_DIR = join(homedir(), ".claude", "skills");

function isSkillDisabled(skillPath: string): boolean {
  try {
    const text = readFileSync(skillPath, "utf-8");
    if (!text.startsWith("---")) return false;
    const end = text.indexOf("---", 3);
    if (end === -1) return false;
    const frontmatter = text.slice(3, end);
    for (const line of frontmatter.split("\n")) {
      if (line.trim().startsWith("disabled:") && line.trim().endsWith("true")) {
        return true;
      }
    }
  } catch {
    // ignore read errors
  }
  return false;
}

function discoverSkills(): Set<string> {
  if (!existsSync(RAW_SKILLS_DIR)) return new Set();

  // Ensure the CLI skills directory exists (writable tmpfs)
  mkdirSync(SKILLS_DIR, { recursive: true });

  const validSkills = new Set<string>();

  for (const d of readdirSync(RAW_SKILLS_DIR, { withFileTypes: true })) {
    if (!d.isDirectory()) continue;
    const rawPath = join(RAW_SKILLS_DIR, d.name, "SKILL.md");
    if (!existsSync(rawPath) || isSkillDisabled(rawPath)) continue;

    validSkills.add(d.name);

    // Create/update flat .md file so the CLI's Skill tool can find it
    try {
      const content = readFileSync(rawPath, "utf-8");
      writeFileSync(join(SKILLS_DIR, `${d.name}.md`), content);
    } catch {
      // ignore write errors (e.g. permissions)
    }
  }

  // Remove stale flat files for skills that no longer exist or are disabled
  try {
    for (const f of readdirSync(SKILLS_DIR)) {
      if (f.endsWith(".md") && !validSkills.has(f.slice(0, -3))) {
        unlinkSync(join(SKILLS_DIR, f));
      }
    }
  } catch {
    // ignore cleanup errors
  }

  return validSkills;
}

